CREATE TABLE public.cultural_inspirations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, creator_id uuid NOT NULL, partner_id uuid, category text NOT NULL CHECK (category IN ('Food','Art','Song','Language','Tradition','Your own idea')), mode text NOT NULL DEFAULT 'solo' CHECK (mode IN ('solo','team','challenge')), title text NOT NULL DEFAULT '' CHECK (length(title)<=120), photo_path text, needs text NOT NULL DEFAULT '' CHECK (length(needs)<=2000), backstory text NOT NULL DEFAULT '' CHECK (length(backstory)<=3000), steps text NOT NULL DEFAULT '' CHECK (length(steps)<=5000), meaning text NOT NULL DEFAULT '' CHECK (length(meaning)<=2000), song_artist text CHECK (length(song_artist)<=120), song_url text CHECK (length(song_url)<=500), reveal_on date NOT NULL DEFAULT CURRENT_DATE, feature_later boolean NOT NULL DEFAULT false, hidden_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cultural_inspirations TO authenticated;
GRANT ALL ON public.cultural_inspirations TO service_role;
ALTER TABLE public.cultural_inspirations ENABLE ROW LEVEL SECURITY;
CREATE POLICY inspiration_read ON public.cultural_inspirations FOR SELECT TO authenticated USING (trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()) AND (creator_id=auth.uid() OR partner_id=auth.uid() OR (reveal_on <= CURRENT_DATE AND hidden_at IS NULL)));
CREATE POLICY inspiration_insert ON public.cultural_inspirations FOR INSERT TO authenticated WITH CHECK (creator_id=auth.uid() AND trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()) AND (partner_id IS NULL OR (partner_id<>auth.uid() AND trip_private.is_trip_member(trip_id,partner_id))));
CREATE POLICY inspiration_update ON public.cultural_inspirations FOR UPDATE TO authenticated USING (hidden_at IS NULL AND trip_private.feature_on(trip_id,'inspiration') AND (creator_id=auth.uid() OR (mode='team' AND partner_id=auth.uid()))) WITH CHECK (hidden_at IS NULL AND trip_private.feature_on(trip_id,'inspiration') AND (creator_id=auth.uid() OR (mode='team' AND partner_id=auth.uid())));
CREATE POLICY inspiration_delete ON public.cultural_inspirations FOR DELETE TO authenticated USING (creator_id=auth.uid());
CREATE OR REPLACE FUNCTION trip_private.inspiration_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.trip_id<>OLD.trip_id OR NEW.creator_id<>OLD.creator_id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id OR NEW.hidden_at IS DISTINCT FROM OLD.hidden_at OR NEW.mode<>OLD.mode THEN RAISE EXCEPTION 'Experience ownership cannot be changed'; END IF; END IF; IF NEW.partner_id IS NOT NULL AND NOT trip_private.is_trip_member(NEW.trip_id,NEW.partner_id) THEN RAISE EXCEPTION 'Partner must be in the squad'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER inspiration_validate BEFORE INSERT OR UPDATE ON public.cultural_inspirations FOR EACH ROW EXECUTE FUNCTION trip_private.inspiration_validate();
REVOKE ALL ON FUNCTION trip_private.inspiration_validate() FROM PUBLIC, anon;
CREATE TABLE public.inspiration_votes (card_id uuid NOT NULL REFERENCES public.cultural_inspirations(id) ON DELETE CASCADE, voter_id uuid NOT NULL, choice text NOT NULL CHECK (choice IN ('creator','partner','love')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(card_id,voter_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.inspiration_votes TO authenticated;
GRANT ALL ON public.inspiration_votes TO service_role;
ALTER TABLE public.inspiration_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY inspiration_votes_read ON public.inspiration_votes FOR SELECT TO authenticated USING (voter_id=auth.uid() OR EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid())));
CREATE POLICY inspiration_votes_insert ON public.inspiration_votes FOR INSERT TO authenticated WITH CHECK (voter_id=auth.uid() AND EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (choice='love' OR (c.mode='challenge' AND c.partner_id IS NOT NULL AND auth.uid() NOT IN (c.creator_id,c.partner_id)))));
CREATE POLICY inspiration_votes_update ON public.inspiration_votes FOR UPDATE TO authenticated USING (voter_id=auth.uid()) WITH CHECK (voter_id=auth.uid());
CREATE POLICY inspiration_votes_delete ON public.inspiration_votes FOR DELETE TO authenticated USING (voter_id=auth.uid());
CREATE TABLE trip_private.inspiration_moderation (id bigserial PRIMARY KEY, card_id uuid NOT NULL, actor uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.hide_inspiration(p_card uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; UPDATE public.cultural_inspirations SET hidden_at=now() WHERE id=p_card AND hidden_at IS NULL; IF FOUND THEN INSERT INTO trip_private.inspiration_moderation(card_id,actor,action) VALUES(p_card,auth.uid(),'hide'); END IF; END $$;
REVOKE ALL ON FUNCTION public.hide_inspiration(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hide_inspiration(uuid) TO authenticated;
UPDATE trip_private.preview_settings SET features=features||'{"inspiration":false}'::jsonb;